  glass: [236, 240, 240],   // window pane
  glow: [255, 246, 224],    // emissive surface (lit lampshade)
  dark: [46, 46, 52],       // the rare deliberate dark fill
  ink: [23, 23, 28],
  inkMid: [70, 70, 78],
  inkSoft: [128, 128, 136],
  accent: [176, 92, 62],    // warm terracotta used very sparingly
  sky: [232, 240, 246],
